import type { Question, RegionId } from './types'

/** Opción múltiple: la primera opción de la lista es la correcta (se barajan al jugar). */
function mc(id: string, region: RegionId, kind: 'caso' | 'dato', q: string, correct: string, wrong: string[], explain: string): Question {
  return { id, region, kind, q, options: [correct, ...wrong], answer: 0, explain }
}
/** Verdadero / Falso */
function vf(id: string, region: RegionId, q: string, isTrue: boolean, explain: string): Question {
  return { id, region, kind: 'vf', q, options: ['Verdadero', 'Falso'], answer: isTrue ? 0 : 1, explain }
}

